"""Search-first entrance to the free encyclopedia, without competing promotions."""
import json,re
from pathlib import Path
from html import escape as e
R=Path(__file__).resolve().parents[1]
count=len(list((R/'content/guides').glob('*.json')))
paths=[('Emergencies','Handle an emergency','Find the first protective steps for what is happening.','/emergencies/'),('Preparedness','Start preparing','Build a household plan, one useful step at a time.','/preparedness/'),('Knowledge','Explore the library','Browse practical guides by subject.','/library/')]
choices=''.join(f'<a class="entry-path" href="{url}"><span class="entry-label">{label}</span><h2>{title}</h2><p>{desc}</p><span class="entry-arrow" aria-hidden="true">↗</span></a>' for label,title,desc,url in paths)
quick=[('Power outage','/emergencies/power-outage/','Lighting, food & backup power'),('Unsafe water','/emergencies/water-disruption/','Understand the notice'),('Severe weather','/emergencies/severe-weather/','Find the specific hazard'),('Evacuation','/emergencies/evacuation/','Leaving with a plan'),('First aid','/library/medical/','Find the right response'),('Home fire','/emergencies/home-fire/','Get out and stay out')]
quicklinks=''.join(f'<a class="home-situation" href="{url}"><strong>{e(title)}</strong><span>{e(desc)}</span><b aria-hidden="true">↗</b></a>' for title,url,desc in quick)
main=f'''<main id="main" class="home-page polished-home">
<section class="wrap home-hero field-hero" aria-labelledby="hero-title">
<div class="home-hero-stage"><div class="home-hero-intro"><div class="hero-masthead"><p class="kicker">THE PREPAREDNESS LIBRARY<br><span>CIVILIAN KNOWLEDGE. FREE ACCESS.</span></p><img src="/Assets/oz-mark.webp" alt="" width="52" height="52"></div><div class="hero-editorial-lockup"><h1 id="hero-title"><span>SKILL </span><span>BEATS </span><span class="hero-panic">PANIC.</span></h1><p class="hero-everytime">Every<br>time.</p></div><p class="home-lede">Practical guidance for emergencies and everyday preparedness.</p><div class="finder-bar home-finder"><label for="emergency-search">Search {count} free guides</label><div class="search-control"><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="emergency-search" type="search" placeholder="What do you need to know?" autocomplete="off" autocorrect="off" autocapitalize="none" spellcheck="false" enterkeyhint="search" aria-controls="home-search-results"></div><span class="finder-count" id="finder-count" role="status" aria-live="polite" aria-atomic="true">No account. No signup. Just useful knowledge.</span></div><div id="home-search-results" class="search-results" hidden></div></div>
</div>
<div class="hero-urgent" aria-label="Urgent situations"><span>Need a first step now?</span><a href="/emergencies/cpr/">Adult not breathing</a><a href="/emergencies/choking/">Adult/child choking</a><a href="/emergencies/gas-leak/">Smell gas</a><a href="/emergencies/home-fire/">Fire</a></div><noscript><p>Search needs JavaScript. <a href="/library/">Browse all free guides</a>.</p></noscript></section>
<section class="wrap entry-paths" aria-label="Choose where to start">{choices}</section>
<section class="wrap home-common" id="find-help" aria-labelledby="common-title"><div class="home-section-heading"><h2 id="common-title">Common situations</h2><a class="text-link" href="/emergencies/">All emergency guides →</a></div><div class="topic-grid home-situation-grid" id="topic-grid">{quicklinks}</div></section>
<section class="wrap home-briefing compact-briefing" data-briefing="home" aria-labelledby="start-title"><div class="home-section-heading"><div><p class="kicker">A LITTLE CONTEXT. A BETTER PLAN.</p><h2 id="start-title">Daily Brief</h2></div><a class="home-briefing-local text-link" href="/briefing/">View your area & all reports →</a></div><p class="briefing-schedule">Not live · updated twice daily</p><p class="briefing-status" data-briefing-status role="status" aria-live="polite">Loading stored reports; coverage is incomplete.</p><div class="briefing-card-grid" data-briefing-cards hidden></div><div data-briefing-fallback><p class="briefing-fallback-intro">Reports are loading. You can still explore the free guides.</p><a class="text-link" href="/preparedness/household-emergency-plan/">Make your household plan →</a></div><p class="compact-briefing-note">Reports may be incomplete or delayed. An absent report is not an all-clear.</p><details class="briefing-context"><summary>About these reports</summary><p class="briefing-status-detail" data-briefing-status-detail></p><p>Stored source snapshots, not live alerts. Check the linked source for current instructions. <a href="/briefing/">See sources and coverage in Daily Brief.</a></p></details><noscript><p>Reports need JavaScript and a connection. <a href="/preparedness/">Start preparing</a>.</p></noscript></section>
</main>'''
p=R/'index.html';s=p.read_text();s=re.sub(r'<main id="main".*?</main>',lambda _:main,s,flags=re.S)
s=re.sub(r'<meta name="description"[^>]*>','<meta name="description" content="Find clear first steps for emergencies, make a household plan, or explore 138 free preparedness guides. No account needed.">',s)
s=re.sub(r'<script src="/(?:field-book|briefing-globe).js[^"]*"[^>]*></script>','',s)
if '/briefing.css?' not in s:s=s.replace('</head>','<link rel="stylesheet" href="/briefing.css?v=oz1"><script src="/briefing.js?v=oz1" defer></script></head>')
p.write_text(s)
print(f'Built search-first homepage: {count} guides, three paths, six situations, compact briefing.')
